// Package clirt is the runtime support library for code generated by
// opencligen's urfave/cli v3 output. Generated code calls it to check
// positional arguments and to validate flag values; it is not meant to be
// used directly.
package clirt

import (
	"fmt"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/urfave/cli/v3"
)

// Arg describes a positional argument: how many values it takes and how
// each value is checked.
type Arg struct {
	Name     string
	Min, Max int
	Check    func(string) error // nil accepts any value
}

// CheckArgs enforces the arity and values of a command's positional
// arguments. Values are assigned to arguments in order, each taking as many
// values as it can while leaving enough for the minimums of the arguments
// after it.
func CheckArgs(cmd *cli.Command, specs []Arg) error {
	args := cmd.Args().Slice()
	minTotal, maxTotal := 0, 0
	for _, s := range specs {
		minTotal += s.Min
		maxTotal += s.Max
	}
	if len(args) < minTotal {
		return fmt.Errorf("%s: expected at least %d argument(s), got %d", cmd.FullName(), minTotal, len(args))
	}
	if len(args) > maxTotal {
		return fmt.Errorf("%s: expected at most %d argument(s), got %d", cmd.FullName(), maxTotal, len(args))
	}
	i, reserved := 0, minTotal
	for _, s := range specs {
		reserved -= s.Min
		n := min(s.Max, len(args)-i-reserved)
		if s.Check != nil {
			for _, v := range args[i : i+n] {
				if err := s.Check(v); err != nil {
					return fmt.Errorf("%s: %w", cmd.FullName(), err)
				}
			}
		}
		i += n
	}
	return nil
}

// OneOf accepts only the listed values. name is the flag or argument as the
// user sees it, e.g. "--format" or "<mode>".
func OneOf(name string, accepted ...string) func(string) error {
	return func(v string) error {
		if !slices.Contains(accepted, v) {
			return fmt.Errorf("invalid value %q for %s (accepted: %s)", v, name, strings.Join(accepted, ", "))
		}
		return nil
	}
}

// Number is the set of numeric flag value types.
type Number interface{ ~int | ~uint | ~float64 }

// Between accepts values within the given bounds; a bound only applies when
// its has flag is set.
func Between[T Number](name string, lo T, hasLo bool, hi T, hasHi bool) func(T) error {
	return func(v T) error {
		if hasLo && v < lo {
			return fmt.Errorf("invalid value %v for %s (minimum: %v)", v, name, lo)
		}
		if hasHi && v > hi {
			return fmt.Errorf("invalid value %v for %s (maximum: %v)", v, name, hi)
		}
		return nil
	}
}

// Each applies check to every value of a repeated flag.
func Each[T any](check func(T) error) func([]T) error {
	return func(vs []T) error {
		for _, v := range vs {
			if err := check(v); err != nil {
				return err
			}
		}
		return nil
	}
}

// Bool accepts the values strconv.ParseBool accepts, for boolean options
// that take an explicit value ("-flag true").
func Bool(name string) func(string) error {
	return func(v string) error {
		if _, err := strconv.ParseBool(v); err != nil {
			return fmt.Errorf("invalid value %q for %s (expected true or false)", v, name)
		}
		return nil
	}
}

// Int parses a positional value as an int and applies check, if any.
func Int(name string, check func(int) error) func(string) error {
	return parsed(name, "an integer", func(s string) (int, error) { return strconv.Atoi(s) }, check)
}

// Uint parses a positional value as a uint and applies check, if any.
func Uint(name string, check func(uint) error) func(string) error {
	return parsed(name, "a non-negative integer", func(s string) (uint, error) {
		u, err := strconv.ParseUint(s, 10, 0)
		return uint(u), err
	}, check)
}

// Float parses a positional value as a float64 and applies check, if any.
func Float(name string, check func(float64) error) func(string) error {
	return parsed(name, "a number", func(s string) (float64, error) { return strconv.ParseFloat(s, 64) }, check)
}

// Duration parses a positional value with time.ParseDuration.
func Duration(name string) func(string) error {
	return parsed[time.Duration](name, `a duration such as "1m30s"`, time.ParseDuration, nil)
}

func parsed[T any](name, what string, parse func(string) (T, error), check func(T) error) func(string) error {
	return func(s string) error {
		v, err := parse(s)
		if err != nil {
			return fmt.Errorf("invalid value %q for %s (expected %s)", s, name, what)
		}
		if check != nil {
			return check(v)
		}
		return nil
	}
}
